def compute(vars):
    value = vars["v1"] - vars["v2"]
    return {
        "value": value,
        "trace": {
            "interest_and_penalties": vars["v1"],
            "interest_income": vars["v2"],
            "difference": value,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": None
            }
        }
    }
